const must = (c, m) => { if (!c) throw new Error(m); };
const eq = (a, b, m) => must(JSON.stringify(a) === JSON.stringify(b), `${m}: got ${JSON.stringify(a)}, expected ${JSON.stringify(b)}`);
const mem = (init = {}) => { const m = new Map(Object.entries(init).map(([k, v]) => [k, JSON.stringify(v)])); return { m, get: async k => m.get(k) ?? null, put: async (k, v) => { m.set(k, v); } }; };
const json = body => ({ ok: true, status: 200, json: async () => body });
const HOUR = 3600e3, NOW = Date.parse('2026-06-01T00:00:00Z');
const offline = async () => { throw new Error('offline'); };
const epmc = rows => async u => (/europepmc/.test(u) ? json({ resultList: { result: rows } }) : offline());
const chain = (grades, years = 1) => ({ id: 't', cost: { upfront: 1000, years: 1 }, nodes: grades.map((g, i) => ({ id: 'n' + i, label: 'n' + i, kind: 'direct', parent: i ? 'n' + (i - 1) : undefined, amount: 1, unit: 'wellby', years, grade: g, source: 'test' })) });
const s5 = (m, o = {}) => score(m, { draws: 1000, seed: 3, ...o });
const wbFetch = ({ ind, lower }) => async u => {
  const n = 40, outlier = (i, late) => (i === 0 ? 8 : i === 1 && late ? 8 : 0);
  if (/\/country\?/.test(u)) return json([{}, Array.from({ length: n }, (_, i) => ({ id: 'C' + i, region: { id: 'X' } }))]);
  const m = /date=(\d+):(\d+)/.exec(u), late = Number(m[2]) >= 2020, income = u.includes('NY.GDP.PCAP.PP.CD');
  return json([{}, Array.from({ length: n }, (_, i) => { const x = 1000 * (i + 1), noise = (((i * 7) % 5) - 2) * 0.3; return { countryiso3code: 'C' + i, date: m[2], country: { value: 'Country ' + i }, value: income ? x : 10 + 5 * Math.log(x) + noise + (lower ? -1 : 1) * outlier(i, late) }; })]);
};

export const CTX = { ENGINE, CADENCE, UIA, SCORED_FACTS, COST, ADOPT, CHANNEL_POINTS, MIN_PRACTICAL, READY, RULE, PRIOR_WEIGHT, REDTEAM, RED_POOL, ENSEMBLE, LEDGER: ENSEMBLE_LEDGER, CONTEXTS, FIXED: Object.entries(PARAMS).filter(([, v]) => typeof v.dist === 'number').map(([k, v]) => `${k.replace(/_/g, ' ')} (${v.dist})`) };
const links = Object.values(MODELS).flatMap(m => m.nodes);
CTX.LINKS = links.length; CTX.POINTS = links.filter(n => typeof n.amount === 'number').length;

